<script lang="ts">
  import { formatCompactHash, formatDateTime } from '../lib/format';
  import type { OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;

  $: reviewQueue = Object.entries(operations.discovery_queue ?? {})
    .filter(([state]) => ['validated', 'ambiguous', 'failed', 'registration_only', 'future_publication'].includes(state))
    .reduce((total, [, count]) => total + count, 0);
  $: provenance = operations.operational_provenance;
</script>

<details class="operations-disclosure">
  <summary>
    <span><span class="disclosure-icon" aria-hidden="true">i</span><strong>Operação e rastreabilidade</strong></span>
    <small>Saúde, fila e hashes do run</small>
  </summary>
  <div class="operations-disclosure-body">
    <dl>
      <div><dt>Watcher</dt><dd>{operations.service_running ? 'Em execução' : 'Preparado, sem processo detectado'}</dd></div>
      <div><dt>Última checagem</dt><dd>{operations.last_source_check ? formatDateTime(operations.last_source_check) : 'Não registrada'}</dd></div>
      <div><dt>Adapters</dt><dd>{operations.adapter_health.healthy} saudáveis · {operations.adapter_health.degraded} degradados · {operations.adapter_health.failed} falhos</dd></div>
      <div><dt>Fila de revisão</dt><dd>{reviewQueue} itens</dd></div>
      <div><dt>Run vivo</dt><dd><code>{operations.run_id}</code></dd></div>
      {#if provenance}
        <div><dt>Dados</dt><dd><code title={provenance.data_hash}>{formatCompactHash(provenance.data_hash)}</code></dd></div>
        <div><dt>Config</dt><dd><code title={provenance.config_hash}>{formatCompactHash(provenance.config_hash)}</code></dd></div>
        <div><dt>Resultado</dt><dd><code title={provenance.artifact_hashes.result}>{formatCompactHash(provenance.artifact_hashes.result)}</code></dd></div>
      {/if}
    </dl>
    <p><strong>Dados atualizam; método não se autoajusta.</strong> {operations.methodology.rule}</p>
    <a href="/laboratorio" data-route>Ver laboratório e diagnóstico completo →</a>
  </div>
</details>
