<script lang="ts">
  import { onMount } from 'svelte';
  import { candidateMedia } from '../lib/candidateMedia';
  import {
    applyWindow,
    equivalentPeriods,
    periodLabel,
    PERIODS,
    readChartQuery,
    referenceDate,
    REFERENCE_DATE_LABEL,
    shareScale,
    writeChartQuery,
    type ChartKind,
    type PeriodId,
  } from '../lib/chartState';
  import { formatDate, formatPublishedNumber } from '../lib/format';
  import type { LivePoll } from '../lib/types';

  export let livePolls: LivePoll[];
  export let runId: string;

  type ChartCandidate = { id: string; label: string; color: string };

  const colors = ['#1f65d6', '#5b6b82', '#7c5cc4', '#14806b', '#c1652c', '#2f7eaa'];
  const TOP_N = 6;

  let period: PeriodId = '30';
  let kind: ChartKind = 'bars';
  let hidden = new Set<string>();
  let showAll = false;
  let hovered: { poll: LivePoll; candidate: ChartCandidate; value: number; x: number; y: number } | null = null;
  let ready = false;

  const identity = (poll: LivePoll) => poll.registration_no || poll.scenario_id;

  onMount(() => {
    const sync = () => {
      const query = readChartQuery(window.location.search);
      period = query.periodo ?? '30';
      kind = query.grafico ?? 'bars';
      hidden = new Set(query.series ?? []);
      ready = true;
    };
    sync();
    window.addEventListener('popstate', sync);
    return () => window.removeEventListener('popstate', sync);
  });

  function persist(mode: 'push' | 'replace'): void {
    if (!ready) return;
    writeChartQuery(
      { periodo: period, grafico: kind, series: [...hidden].sort() },
      '',
      mode,
    );
  }

  function selectPeriod(next: PeriodId): void {
    period = next;
    hovered = null;
    persist('push');
  }

  function selectKind(next: ChartKind): void {
    kind = next;
    hovered = null;
    persist('replace');
  }

  function toggleCandidate(id: string): void {
    const next = new Set(hidden);
    if (next.has(id)) next.delete(id);
    else if (visibleCandidates.length > 1) next.add(id);
    hidden = next;
    persist('replace');
  }

  $: latest = [...livePolls].sort((a, b) => referenceDate(b).localeCompare(referenceDate(a)))[0];
  $: allCandidates = (latest?.values ?? []).map((value, index): ChartCandidate => ({
    id: value.candidate_id,
    label: candidateMedia(value.candidate_id, value.label).displayName,
    color: colors[index % colors.length],
  }));
  $: rosterCandidates = showAll ? allCandidates : allCandidates.slice(0, TOP_N);
  $: omittedCount = Math.max(0, allCandidates.length - rosterCandidates.length);
  $: visibleCandidates = rosterCandidates.filter((candidate) => !hidden.has(candidate.id));

  $: windowResult = applyWindow(livePolls, period);
  $: filtered = [...windowResult.polls].sort((a, b) =>
    referenceDate(a).localeCompare(referenceDate(b)),
  );
  $: sameAs = equivalentPeriods(livePolls, period, identity).map((id) =>
    PERIODS.find((option) => option.id === id)?.label ?? id,
  );

  // Only a house that measured the same roster twice inside the window can be
  // drawn as a line. Connecting two different houses would invent a trend.
  $: seriesByHouse = (() => {
    const grouped = new Map<string, LivePoll[]>();
    filtered.forEach((poll) => {
      const key = `${poll.institute_id}|${poll.values.map((value) => value.candidate_id).sort().join(',')}`;
      grouped.set(key, [...(grouped.get(key) ?? []), poll]);
    });
    return [...grouped.values()].filter((polls) => polls.length >= 2);
  })();
  $: linesAvailable = seriesByHouse.length > 0;
  $: effectiveKind = kind === 'lines' && !linesAvailable ? 'bars' : kind;

  $: shownValues = filtered.flatMap((poll) =>
    poll.values
      .filter((value) => visibleCandidates.some((candidate) => candidate.id === value.candidate_id))
      .map((value) => value.pct),
  );
  $: scale = shareScale(shownValues);
  $: measurementLabel =
    filtered.length === 1 ? '1 medição publicada' : `${filtered.length} medições publicadas`;

  const PLOT = { left: 92, right: 700, top: 24, bottom: 268 };
  $: plotWidth = PLOT.right - PLOT.left;
  $: plotHeight = PLOT.bottom - PLOT.top;

  function yFor(value: number): number {
    const clamped = Math.min(scale.max, Math.max(scale.min, value));
    return PLOT.bottom - ((clamped - scale.min) / (scale.max - scale.min)) * plotHeight;
  }

  $: groupWidth = filtered.length ? plotWidth / filtered.length : plotWidth;
  $: barWidth = visibleCandidates.length
    ? Math.min(26, (groupWidth * 0.74) / visibleCandidates.length)
    : 0;

  function groupCentre(index: number): number {
    return PLOT.left + groupWidth * (index + 0.5);
  }

  function barX(pollIndex: number, seriesIndex: number): number {
    const total = visibleCandidates.length * barWidth;
    return groupCentre(pollIndex) - total / 2 + seriesIndex * barWidth;
  }

  function pointX(poll: LivePoll): number {
    const index = filtered.findIndex((item) => identity(item) === identity(poll));
    if (index < 0) return groupCentre(0);
    return groupCentre(index);
  }

  function valueOf(poll: LivePoll, candidateId: string): number | undefined {
    return poll.values.find((value) => value.candidate_id === candidateId)?.pct;
  }

  function tooltipFor(poll: LivePoll, candidate: ChartCandidate): string {
    const value = valueOf(poll, candidate.id);
    const parts = [
      `${candidate.label}: ${value === undefined ? '—' : `${formatPublishedNumber(value)}%`}`,
      `Casa: ${poll.institute}`,
      `Campo: ${formatDate(poll.field_start)} a ${formatDate(poll.field_end)}`,
      `Publicação: ${formatDate(poll.published_at)}`,
      `Amostra: ${poll.sample_size ? poll.sample_size.toLocaleString('pt-BR') : 'não informada'}`,
      `Modo: ${poll.mode}`,
      `Registro: ${poll.registration_no || 'não informado'}`,
      `Base: ${poll.base}`,
    ];
    return parts.join(' · ');
  }

  function handleChartKey(event: KeyboardEvent): void {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    (event.currentTarget as HTMLElement).scrollBy({
      left: event.key === 'ArrowRight' ? 120 : -120,
      behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
    });
  }
</script>

<section class="live-chart-card" aria-labelledby="live-chart-title">
  <header class="section-title-row">
    <div>
      <p class="mini-label">Pesquisas publicadas</p>
      <h2 id="live-chart-title">{measurementLabel}</h2>
      <p>
        Valores como cada casa publicou, sem ajuste do modelo.
        {#if windowResult.from && windowResult.to}
          Intervalo efetivo: {formatDate(windowResult.from)} a {formatDate(windowResult.to)}.
        {/if}
      </p>
    </div>
    <div class="chart-control-stack">
      <div class="period-tabs" role="group" aria-label="Período do gráfico">
        {#each PERIODS as item}
          <button
            type="button"
            class:active={period === item.id}
            aria-pressed={period === item.id}
            onclick={() => selectPeriod(item.id)}
          >{item.label}<span class="sr-only"> — {item.full}</span></button>
        {/each}
      </div>
      <div class="period-tabs" role="group" aria-label="Tipo de gráfico">
        <button type="button" class:active={effectiveKind === 'bars'} aria-pressed={effectiveKind === 'bars'} onclick={() => selectKind('bars')}>Barras</button>
        <button
          type="button"
          class:active={effectiveKind === 'lines'}
          aria-pressed={effectiveKind === 'lines'}
          disabled={!linesAvailable}
          title={linesAvailable ? undefined : 'Nenhuma casa tem duas medições comparáveis nesta janela'}
          onclick={() => selectKind('lines')}
        >Linhas</button>
      </div>
    </div>
  </header>

  {#if sameAs.length}
    <p class="chart-window-note" role="status">
      As mesmas {filtered.length} pesquisas estão em {period === 'campaign' ? 'Campanha' : `${period}D`} e em {sameAs.join(', ')}.
      Nada muda porque não há pesquisa fora deste intervalo — não porque o filtro esteja inativo.
    </p>
  {/if}
  {#if kind === 'lines' && !linesAvailable}
    <p class="chart-window-note" role="status">
      Uma medição por casa nesta janela; ainda não há linha intracasas. Mostrando barras.
      Ligar casas diferentes sugeriria uma tendência que os dados não têm.
    </p>
  {/if}

  <div class="chart-legend" role="group" aria-label="Séries exibidas — use para mostrar ou ocultar candidaturas">
    {#each rosterCandidates as candidate}
      <button
        type="button"
        class:muted={hidden.has(candidate.id)}
        aria-pressed={!hidden.has(candidate.id)}
        style={`--series-color:${candidate.color}`}
        onclick={() => toggleCandidate(candidate.id)}
      ><span aria-hidden="true"></span>{candidate.label}</button>
    {/each}
    {#if allCandidates.length > TOP_N}
      <button type="button" class="chart-scope-toggle" aria-pressed={showAll} onclick={() => (showAll = !showAll)}>
        {showAll ? `Mostrar principais (${TOP_N})` : `Mostrar todas (${allCandidates.length})`}
      </button>
    {/if}
  </div>
  {#if omittedCount}
    <p class="chart-scope-note">
      O gráfico mostra as {TOP_N} candidaturas com maior percentual na publicação mais recente.
      As {omittedCount} demais estão em “Mostrar todas” e na tabela abaixo.
    </p>
  {/if}

  <p class="chart-swipe-hint">Janela por {REFERENCE_DATE_LABEL}. Deslize ou use as setas para ler o gráfico.</p>
  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
  <div class="live-chart-wrap" tabindex="0" role="region" aria-label="Gráfico de pesquisas publicadas" onkeydown={handleChartKey}>
    {#if filtered.length}
      <svg viewBox="0 0 760 340" role="img" aria-labelledby="chart-svg-title chart-svg-desc">
        <title id="chart-svg-title">Percentuais publicados nas pesquisas nacionais de 2026</title>
        <desc id="chart-svg-desc">
          {filtered.length} pesquisa(s) em {periodLabel(period)}, de {visibleCandidates.length} candidatura(s) exibida(s).
          {effectiveKind === 'bars'
            ? 'Barras agrupadas por pesquisa, casa e data, com eixo iniciando em zero.'
            : 'Linhas ligam apenas medições da mesma casa e do mesmo cenário.'}
        </desc>
        {#each scale.ticks as tick}
          <line class="chart-gridline" x1={PLOT.left - 10} x2={PLOT.right} y1={yFor(tick)} y2={yFor(tick)} />
          <text class="chart-axis-label" x={PLOT.left - 22} y={yFor(tick) + 4} text-anchor="end">{Math.round(tick)}%</text>
        {/each}
        <line class="chart-axis" x1={PLOT.left - 10} x2={PLOT.right} y1={PLOT.bottom} y2={PLOT.bottom} />

        {#if effectiveKind === 'bars'}
          {#each filtered as poll, pollIndex}
            {#each visibleCandidates as candidate, seriesIndex}
              {@const value = valueOf(poll, candidate.id)}
              {#if value !== undefined}
                <rect
                  class="series-bar"
                  x={barX(pollIndex, seriesIndex)}
                  y={yFor(value)}
                  width={Math.max(3, barWidth - 3)}
                  height={Math.max(1, PLOT.bottom - yFor(value))}
                  fill={candidate.color}
                  role="graphics-symbol"
                  tabindex="0"
                  aria-label={tooltipFor(poll, candidate)}
                  data-value={value}
                  data-run-id={runId}
                  data-house={poll.institute}
                  onmouseenter={() => (hovered = { poll, candidate, value, x: barX(pollIndex, seriesIndex), y: yFor(value) })}
                  onmouseleave={() => (hovered = null)}
                  onfocus={() => (hovered = { poll, candidate, value, x: barX(pollIndex, seriesIndex), y: yFor(value) })}
                  onblur={() => (hovered = null)}
                />
                {#if barWidth >= 16}
                  <text class="chart-bar-value" x={barX(pollIndex, seriesIndex) + (barWidth - 3) / 2} y={yFor(value) - 6} text-anchor="middle">{formatPublishedNumber(value)}</text>
                {/if}
              {/if}
            {/each}
          {/each}
        {:else}
          {#each visibleCandidates as candidate}
            {#each seriesByHouse as housePolls}
              {@const points = housePolls
                .map((poll) => ({ poll, value: valueOf(poll, candidate.id) }))
                .filter((item) => item.value !== undefined)}
              {#if points.length >= 2}
                <polyline
                  class="series-line"
                  fill="none"
                  stroke={candidate.color}
                  points={points.map((item) => `${pointX(item.poll)},${yFor(item.value ?? 0)}`).join(' ')}
                />
              {/if}
            {/each}
            {#each filtered as poll}
              {@const value = valueOf(poll, candidate.id)}
              {#if value !== undefined}
                <circle
                  class="series-point"
                  cx={pointX(poll)}
                  cy={yFor(value)}
                  r="5"
                  fill={candidate.color}
                  role="graphics-symbol"
                  tabindex="0"
                  aria-label={tooltipFor(poll, candidate)}
                  onmouseenter={() => (hovered = { poll, candidate, value, x: pointX(poll), y: yFor(value) })}
                  onmouseleave={() => (hovered = null)}
                  onfocus={() => (hovered = { poll, candidate, value, x: pointX(poll), y: yFor(value) })}
                  onblur={() => (hovered = null)}
                />
              {/if}
            {/each}
          {/each}
        {/if}

        {#each filtered as poll, index}
          <line class="date-tick" x1={groupCentre(index)} x2={groupCentre(index)} y1={PLOT.bottom} y2={PLOT.bottom + 6} />
          <text class="chart-date" x={groupCentre(index)} y={PLOT.bottom + 26} text-anchor="middle">{formatDate(referenceDate(poll))}</text>
          <text class="chart-house" x={groupCentre(index)} y={PLOT.bottom + 46} text-anchor="middle">{poll.institute}</text>
        {/each}
      </svg>
      {#if hovered}
        <div class="chart-tooltip" style={`left:${(hovered.x / 760) * 100}%; top:${(hovered.y / 340) * 100}%`} role="status">
          <strong>{hovered.candidate.label}</strong>
          <span>{formatPublishedNumber(hovered.value)}% · {hovered.poll.institute}</span>
          <small>Campo {formatDate(hovered.poll.field_start)}–{formatDate(hovered.poll.field_end)} · publicada {formatDate(hovered.poll.published_at)}</small>
          <small>Amostra {hovered.poll.sample_size?.toLocaleString('pt-BR') ?? '—'} · {hovered.poll.mode} · base {hovered.poll.base}</small>
          <small>Registro {hovered.poll.registration_no || '—'}</small>
        </div>
      {/if}
    {:else}
      <p class="chart-no-data">
        Nenhuma pesquisa em {periodLabel(period)}.
        {#if windowResult.boundary}Nada publicado desde {formatDate(windowResult.boundary)}.{/if}
        Nenhum ponto de outra janela é reaproveitado aqui.
      </p>
    {/if}
  </div>

  <div class="insufficient-note" role="note">
    <span aria-hidden="true">i</span>
    <p>
      <strong>{filtered.length < 3 ? 'Dados insuficientes para inferir movimento.' : 'Estes são valores publicados, não o consenso.'}</strong>
      Diferenças entre casas podem refletir campo, método e amostra. Casas distintas nunca são ligadas como uma série.
    </p>
  </div>

  <details class="chart-data-table">
    <summary>Ver valores em tabela ({filtered.length} pesquisa{filtered.length === 1 ? '' : 's'} em {periodLabel(period)})</summary>
    <div>
      <table>
        <caption class="sr-only">Percentuais publicados por candidatura e pesquisa em {periodLabel(period)}</caption>
        <thead><tr><th scope="col">Candidatura</th>{#each filtered as poll}<th class="num" scope="col">{poll.institute}<small>{formatDate(referenceDate(poll))}</small></th>{/each}</tr></thead>
        <tbody>
          {#each allCandidates as candidate}
            <tr><th scope="row">{candidate.label}</th>{#each filtered as poll}{@const value = valueOf(poll, candidate.id)}<td class="num">{value === undefined ? '—' : `${formatPublishedNumber(value)}%`}</td>{/each}</tr>
          {/each}
        </tbody>
      </table>
    </div>
  </details>
</section>
