<script lang="ts">
  import { formatDate, formatPublishedNumber } from '../lib/format';
  import { candidateMedia } from '../lib/candidateMedia';
  import type { OperationsPayload } from '../lib/types';
  import CandidatePortrait from './CandidatePortrait.svelte';
  import DataGate from './DataGate.svelte';

  export let operations: OperationsPayload;

  type View = 'latest' | 'consensus' | 'chance';
  let selected: View = 'latest';
  let tabButtons: HTMLButtonElement[] = [];

  const tabs: Array<{ id: View; label: string }> = [
    { id: 'latest', label: 'Última pesquisa' },
    { id: 'consensus', label: 'Consenso' },
    { id: 'chance', label: 'Chance de vitória' },
  ];

  $: diagnostic = operations.live_diagnostic;
  $: values = diagnostic?.values ?? [];
  $: unavailable = selected !== 'latest';
  $: displayedValues = unavailable
    ? [...values].sort((a, b) => displayName(a.candidate_id, a.label).localeCompare(displayName(b.candidate_id, b.label), 'pt-BR'))
    : values;
  $: missingPolls = Math.max(0, operations.live_coverage.min_polls - operations.live_coverage.polls);

  function selectTab(index: number): void {
    selected = tabs[index].id;
    tabButtons[index]?.focus();
  }

  function handleTabKey(event: KeyboardEvent, index: number): void {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      selectTab((index + 1) % tabs.length);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      selectTab((index - 1 + tabs.length) % tabs.length);
    } else if (event.key === 'Home') {
      event.preventDefault();
      selectTab(0);
    } else if (event.key === 'End') {
      event.preventDefault();
      selectTab(tabs.length - 1);
    }
  }

  function displayName(candidateId: string, label: string): string {
    return candidateMedia(candidateId, label).displayName;
  }
</script>

<section class="live-market" aria-labelledby="election-title">
  <header class="live-market-header">
    <div>
      <p class="market-kicker">Eleições Gerais · 1º turno</p>
      <h1 id="election-title">Presidência do Brasil <span>2026</span></h1>
      <p class="market-meta">
        {#if diagnostic}
          Última publicação: {formatDate(diagnostic.published_at)} · {diagnostic.institute} · {diagnostic.registration_no}
        {:else}
          Nenhuma pesquisa nacional validada na janela viva.
        {/if}
      </p>
    </div>
    <span class="live-state"><span aria-hidden="true"></span>{operations.processing_state === 'processing' ? 'Atualizando' : 'Dados verificados'}</span>
  </header>

  <DataGate {operations} />

  <div class="market-tabs" role="tablist" aria-label="Tipo de leitura eleitoral">
    {#each tabs as tab, index}
      <button
        bind:this={tabButtons[index]}
        type="button"
        role="tab"
        id={`market-tab-${tab.id}`}
        aria-selected={selected === tab.id}
        aria-controls="candidate-readout"
        tabindex={selected === tab.id ? 0 : -1}
        class:active={selected === tab.id}
        onclick={() => selected = tab.id}
        onkeydown={(event) => handleTabKey(event, index)}
      >{tab.label}</button>
    {/each}
  </div>

  {#if unavailable}
    <div class="market-unavailable" role="status">
      <span aria-hidden="true">—</span>
      <div><strong>{missingPolls ? `Aguardando mais ${missingPolls} pesquisa${missingPolls === 1 ? '' : 's'}` : 'Modelo ainda não elegível'}</strong><p>{selected === 'consensus' ? `O consenso só será calculado quando o gate de ${operations.live_coverage.min_polls} pesquisas / ${operations.live_coverage.min_houses} casas for satisfeito.` : 'Nenhuma chance de vitória é publicada antes do gate e da execução do modelo elegível.'}</p></div>
      <a href="/metodologia#criterios" data-route>Entenda o gate</a>
    </div>
  {/if}

  <div id="candidate-readout" role="tabpanel" aria-labelledby={`market-tab-${selected}`} class="candidate-readout">
    <div class="candidate-columns" aria-hidden="true">
      <span>Candidatura</span><span>{unavailable ? 'Situação' : 'Percentual publicado'}</span><span>Valor</span>
    </div>
    {#if values.length}
      <ol class="candidate-list">
        {#each displayedValues as value}
          <li class:unavailable>
            <CandidatePortrait candidateId={value.candidate_id} label={value.label} />
            <div class="candidate-identity">
              <strong>{displayName(value.candidate_id, value.label)}</strong>
              <span>{value.party} · {value.number}</span>
            </div>
            <div class="candidate-bar-area">
              {#if unavailable}
                <span class="candidate-wait">Aguardando cobertura mínima</span>
              {:else}
                <div class="candidate-bar" aria-hidden="true"><span style={`width:${Math.min(100, Math.max(0, value.pct))}%`}></span></div>
              {/if}
            </div>
            {#if unavailable}
              <span class="candidate-value unavailable-value" aria-label="Indisponível">—</span>
            {:else}
              <strong
                class="candidate-value"
                data-value={value.pct}
                data-kind="Publicado"
                data-run-id={diagnostic?.run_id}
                data-evidence={value.evidence_id}
              >{formatPublishedNumber(value.pct)}%</strong>
            {/if}
          </li>
        {/each}
      </ol>
    {:else}
      <div class="market-empty"><strong>Sem percentuais publicados.</strong><p>O watcher segue buscando pesquisas nacionais verificáveis.</p></div>
    {/if}
  </div>
  <footer class="market-footnote">
    <p>Base: votos totais. Os valores acima pertencem a uma pesquisa publicada e não são previsão.</p>
    <a href="/candidates/2026/manifest.json">Créditos e estado das fotos</a>
  </footer>
</section>
